def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    # divider row: a full row of one non-background colour
    div = None
    for y in range(H):
        if g[y, 0] != bg and np.all(g[y] == g[y, 0]):
            div = y
            break
    out = g.copy()
    seeds = [(y, x, int(g[y, x])) for y in range(H) for x in range(W)
             if y != div and g[y, x] in (1, 2)]
    for half in ("top", "bottom"):
        for (y, x, c) in seeds:
            if (half == "top") != (y < div):
                continue
            toward = 1 if y < div else -1   # step direction toward the divider
            if c == 2:
                rng = range(y + toward, div, toward)
            else:
                end = -1 if toward == 1 else H
                rng = range(y - toward, end, -toward)
            for yy in rng:
                if out[yy, x] == bg:
                    out[yy, x] = c
        emit(out, f"Extended seeds in the {half} half: 2s grow toward the divider line, 1s grow away from it to the border.")
    return out
